+/// Each pass's (station, tip radius) at its plunge: the radial feed
+/// that opens every pass.
+fn plunges(path: &Toolpath) -> Vec<(f64, f64)> {
+    let f = Frame::about(&threaded()).expect("frame");
+    path.moves
+        .iter()
+        .filter(|m| m.kind == MoveKind::Feed && m.arc.is_none())
+        .map(|m| f.sr(m.to))
+        .collect()
+}
